import { Injectable } from '@angular/core';
import { Aircrafts } from './aircrafts.service';
import { HttpClient, HttpHeaders, HttpParams } from '@angular/common/http';
import { UserHttpService } from '../user-http.service';
import { HttpErrorResponse } from '@angular/common/http';
import { catchError, Observable, throwError } from 'rxjs';


export interface Tickets{
  readonly _code : string,
  user :string,
  seat : string,
  flight : string,
  price : number,
  numBag : number
}

@Injectable({
  providedIn: 'root'
})


export class TicketsService {

  constructor(private http: HttpClient, private us : UserHttpService) { }

    private handleError(error: HttpErrorResponse) {
      if (error.error instanceof ErrorEvent) {
        // A client-side or network error occurred. Handle it accordingly.
        console.error('An error occurred:', error.error.message);
      } else {
        // The backend returned an unsuccessful response code.
        // The response body may contain clues as to what went wrong,
        console.error(
        `Backend returned code ${error.status}, ` +
        'body was: ' + JSON.stringify(error.error));
      }

      return throwError(() => new Error('Something bad happened; please try again later.') );
    }

    private create_options( params = {} ) {
      return  {
        headers: new HttpHeaders({
          authorization: 'Bearer ' + this.us.get_token(),
          'cache-control': 'no-cache',
          'Content-Type':  'application/json',
        }),
        params: new HttpParams( {fromObject: params} )
      };

    }

  getTicketsByAirline(id : string) : Observable<Tickets[]>{
    return this.http.get<Tickets[]>(this.us.url + '/tickets/' + id, this.create_options()).pipe(
      catchError(this.handleError)
    );
  }

  getTicketsByPassenger(id : string) : Observable<Tickets[]> {
    return this.http.get<Tickets[]>(this.us.url + '/tickets/' + id, this.create_options()).pipe(
      catchError(this.handleError)
    );
  }
}
